  VALUES 
    (234::BIGINT, 'El profe se nota que esta mas que calificado para dar las clases, sabe demasiadas cosas, es muy buena personas y bueno el curso es dificil pero el graba todas sus clases tmb siempre que le preguntas algo el intenta ayudarte en lo que pueda si puede matricule con el es el goat'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '5d6fdc9aa1b17a0f8b828a8514804ebdc7b605f9ca4c13549e3fd50530458fcf'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'es muy buena gente y ayuda bastante si uno le pregunta, tiene pinta de ser odioso xd pero nqv es buena nota las clases se hacen largas pero a veces las graba y eso ayuda los asistentes califican suave y si les manda correo con algún reclamo le resuelven rápido también da mucha práctica metan con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'e5feed14c5919afe3bd029878365ca8d628c05a3c83a8ed17868766b16184d75'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Creo que para resistencia, es la mejor opción, es un buen profesor, es muy justo, si lo da semipresencial suele hacer clases pregrabadas, lo cual ayuda mucho , hay que estudiar mucho y practicar, suele dar buenas recomendaciones para los examenes !'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd97d518a5e8e0a3262d9dea9749ef9b5b2f548d88df0434ede502ccfa1685240'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Ya todos sabemos que Dibujo es una materia complicada para iniciar el semestre, yo personalmente lo repetí un par de veces, pero siento yo que este profe es muy justo y enseña super bien. Pese a su actitud tosca el es muy considerado hacia los estudiantes y siempre buscará una manera de que ud cumpl'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, '07c44c8ba70eaf2985c18aa5e75cb2101080b709b0d7cea55c4cc4a2ac1babca'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Muy buen profe, eso si, la materia es bastante complicada por lo que no esperes pasar facil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2026-01-12T00:00:00+00:00'::TIMESTAMPTZ, '908de45f02785a216bbccf0cd05df555f0626da6a63cb4765bf82277b2535b02'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Una teja de profe, explica bien, califica normal. Lo bueno es que graba las clases, atiende súper rápido el correo. Eso sí, lo ideal sería hacer buenas preguntas, porque preguntar cosas obvias o que se supone que se vieron en clase, quizás ouede provocar un disgusto en él y termine con un regañito.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'd9b27aa25b08d8b1012c95bd3390b196f3fe5981d848b99acaed50f83fc94e0f'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Es súper buena gente pero se nota que no se prepara la materia. La mitad de la clase es él tratando de recordar cómo se resuelven los ejercicios. Dentro de todo, explica bien y califica muy justo. Es la mejor opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '3bee846b7928205c370a8b09571e9fe4a2dc5d5f3f699bd3f2777ab8689e9de8'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Excelente profesor la verdad se ve que sabe un montón y explica super bien es justo y si le pides ayuda te lo da tampoco regala las cosas pero tampoco te mata calificando, lo recomiendo de lo mejor en dibujo técnico.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'e226c233d22f8d80f298b2db201d97b3a41d48102289bac70415e120d5d702de'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Noel es un profe excelente, explica súper bien y califica justo. Los quices no los tira a matar pero tampoco los regala y en consulta ayuda mucho'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-14T00:00:00+00:00'::TIMESTAMPTZ, '807c94f1bc80c9f763539199a83e65babb9d102f3ce31e81ede8202c841f0572'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'El mejor profe que he conocido en el tec, hace el curso suuper ameno y tranquilo. El profe es super comprensivo y busca que le vaya bien, solo preste atención en las clases y haga las tareas con tiempo. Suele grabar las clases (virtual y presencial) por si alguien quiere repasar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-02T00:00:00+00:00'::TIMESTAMPTZ, '17480d345a187c8fe57b1599b065600725a26fd84ab82712d04943a808d25ca2'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'La claridad de la explicación es muy buena además que siempre está dispuesto a explicar. En si el curso es pesado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '1c26ead9bea9685b1a7525bdc50a94b66cafe9d7ef8731c3ed43b1784b5c87db'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El profe explica super bien, el curso es bastante dificil, sin embargo el profe en clase hace mucha práctica, y lo mejor es que deja las clases grabadas, eso ayuda un montón, el lo ayuda a uno si ve que uno le pon e bastante.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '806ef240aca36490122914bd08d85dfca4213155a9e4004bdf8bfffc10e2b0c6'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Excelente profesor, la materia es bastante ruda pero él ayuda un montón. Explica muy bien y si uno lo necesita se lo explica de nuevo, graba las clases y volver a verlas sirve para el examen. Muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a38d666b523a4184621365657be63bb6e9a9685a5a652a896f35d5e4bcfb4369'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El curso es pesado, dejan tareas todas las semanas, sin embargo, con Noel no se hace tan pesado, las tareas las califica el asistente, pero si usted tiene algún reclamo, él está dispuesto a escuchar. Si usted se muestra interesado desde un inicio, y si él ve que usted le puso, él le va a ayudar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'be1c1566f6e6f06912f501c25371d1b7cbbca5d055a50605ba399644e7b3f08e'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Es un profe excelente que entiende super bien la materia y sabe enseñarla, durante las clases hace prácticas y bastantes eran exámenes viejos, a uno lo prepara bastante bien. Solo es bastante intenso con las normas, pero nada demasiado importante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c3fa3b5d5331e7c8d28ec4638d092c2d7f704bc8bcfeb9513cb2a3e7d9cc311d'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Hágase un favor y matricule con Noel. Es un excelente profe, explica súper claro, ayuda un montón y es paciente. Las clases son entretenidas y realmente lo prepara muy bien a uno para los exámenes, tareas y proyecto del curso. Lo volvería a llevar con él sin ninguna duda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7f0f3804390574351cf40412fcecbb7fc562b86a153ef1be44d1554799d5e5d3'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El profe es muy buena nota pero es un poco presumido, es muy paciente al explicar y con las personas que no entienden mucho'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'dfa43b65a52ec206045f3a28d909793fe58360f28a6e43bcf3542902ebb43bde'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2024-03-09T00:00:00+00:00'::TIMESTAMPTZ, '34e2ec7a2f47f19ff40dda552df29066dfc7e9fec93d08a552545dc1a3b34e60'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El profesor es un poco disperso, pero se entiende muy bien como explica la materia, es justo con las calificaciones y le puede ayudar si usted necesita ayudas o si le calificaron mal algo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-05T00:00:00+00:00'::TIMESTAMPTZ, '10e0688e5f2fd48ae22793e4271c5ce1873341c5f9a75236f8c9ca2544fdbf0c'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El profe este semestre estuvo bastante disperso. Muchas clases perdidas, es la primera vez que da el curso, nos trató bien a la mayoría, muy comprensivo y si usted tiene dudas puede preguntar sin miedo. Pese a las falencias con respecto al curso, sigue siendo uno de los mejores profes de la escuela.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8e80b8446c1d780a9506dbd4dab2f70d03a787178aaa09dababffda394da1fc3'::TEXT, ARRAY[989]::BIGINT[]),
    (234::BIGINT, 'Resis es un curso muy difícil, pero este profe lo hace pasable, resuelve muchísimos ejercicios muy útiles en la clase, hace quizes proporcionales a la materia que se ve. 10/10, super recomendado'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'e1f7525a3f013819a62d2d3d972397986b0b411c2528fb5fe02ddb584a67adf1'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Se nota que sabe mucho sobre el tema. Si uno va a las clases y a las sesiones de consulta, siempre le va a quedar todo claro y va a aprender mucho. Como persona, es bastante estricto con las calificaciones pero también es muy flexible con las entregas y también justo. En general, muy buen profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a3cd04445e25332cbdd3ab2a576f42010d8f061cbf3e3bf79c28a4b6e25a5f3a'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Es un profesor con el que tienes que ir a consulta para estar siempre al día, porque con la clase nunca es suficiente. Es flexible con las entregas pero si revisa algunas veces estricto los trabajos. Y deja trabajos largos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '18bbf0c02ce0a0e4fe726902dbb77d594b1c49b59935ddf35fd1c372f1ad891d'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'El curso requiere que uno estudie y practique moderadamente fuera de clase. El profe enseña haciendo ejemplos y aclara dudas en el camino. Puede ser gracioso, pero tampoco es un payaso. La clase es amena. Se interesa bastante en que le entiendan y aprendan, no es maldoso como otros profes del área.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7e3bee71436d242809214ebb71f914e8dcfad87ee5b8b503744cfd1cb7b52a58'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Resis de por sí ya es un curso matado, el profe lo hace más ameno, pero no le quita que en los examenes salga uno majado. Explica ejercicios, no se mete tanto con la teoría, se enreda en ocasiones y normalmente usa solucionario ya que no le dan los ejercicios a la primera.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3b0c337d907a561eb0efcbe0418f127bd9030b370d1b2c85eb6ea883512210cb'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'El profe es muy buena gente, y tiene mucha disposición para repetir las veces que sea necesario para que todos entienda. Si van a llevar con el es importante llevar las clases al día ya que el curso es un poco complicado. Y si no entiende preguntar e ir a las horas de consulta'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0c4370fd9da4164a0a33da3d662dbf423d2314d61efc429f97aa324f6b983512'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El profe es demasiado bueno, a veces se enreda, pero siempre está dispuesto a repetir, él es súper pura vida.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9f20aa038d4281c157e29fdae2c087802627febd49f0120e65cb4346adcdd510'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Tal vez el mejor profesor de su escuela. Explica muy bien, paso a paso, aclarando todas las dudas que tengan los estudiantes. Es muy comprensivo y flexible con las entregas de tareas y la aplicación de quices. Por si fuera poco, es una tejota y las clases son amenas. No lo podría recomendar más.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'ce29e0b4064504fa491bb02e9c7673c6749457b6933952f58d7d6672b0777860'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Se nota que le interesa que uno aprenda y resuelve muchos ejercicios paso por paso. A veces se enreda mucho pero igual trata de resolver el problema. De los mejores de la escuela.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '9022d173f23f3a4ca1f94f2522abeaacbbf3cf0d4f00ce23ece2b12fd8209885'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Es un buen profesor, el curso es pesado y feo, pero el es paciente con los estudiantes y es flexible con la entrega de trabajos, recomendado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'cf4e3e3b91634e70931d268379762c21eb011c31ddba41af02f93ba0394c4eac'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Fue muy bueno durante todo el curso, domina muy bien todos los temas y siempre resolvía ejercicios similares a los que salían en los quices o exámenes además no llegaba solamente a leer la presentación como si lo hacen otros, resuelve siempre todos los ejercicios de diferentes maneras.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'f7a4e3a224a4ba2acd26c388f1f581de6fdc11a3712c0575ac277d0fe8992e55'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'El curso es demasiado pesado, el profe explica bien, repite si es necesario, lo más importante es que tiene consideración con el estudiante por lo que es flexible si hay que pasar tareas o proyectos, para DI lo recomiendo es de los mejores.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'f4a6626d63e23a27b0551abc2b3699856f41c14bb51be27f6fd08d5b500b639b'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'El curso es muy pesado pero el profe lo entiende e intenta ayudarle a uno. Explica bastante bien y en consulta ayuda bastante, solo que a veces parece que quiere salir rápido del asunto. Lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-28T00:00:00+00:00'::TIMESTAMPTZ, 'e60084733015de411355c97578a5ed7d0f74652cfccf0287a03b1c3c3bc396c9'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'El curso es rudo, pero el profe es de los mejores. Explica super bien y es super comprensivo. Lo recomiendo muchísimo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '581becd9f73b3831a3e958fa6b2fe34d423daf4e3851a69c63e2f10c2d00e11a'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'Al principio muy bueno, conforme avanza el curso va bajando el nivel y explica a partir del solucionario. Regala los quices.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd849a5bff5ea662ab7d29a11a7eef1b12770473cbeae2039fe4e3a7adc3f7045'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Fue la primera vez que dió el curso, al inicio un excelente profesor, luego fue bajando el nivel tanto así que al final proyectaba el solucionario y esas eran las clases. Sin embrago, el curso no es fácil que digamos hasta el mismo profe esta bateado en algunos temas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0f48144647338057afe161badce10bfe9033b934ee5c23ff2d1a1c85b8687e23'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9c883bfc80b9df21f64a7a83d89e0f924811f9d870233c64b1e94d32c804c348'::TEXT, ARRAY[945]::BIGINT[]),
    (234::BIGINT, 'Este curso es pesadísimo, independientemente del profe que se escoja. No lleva mucho dando el curso pero sabe bastante y se toma su tiempo para que todos entiendan la materia, ayudan un montón en consulta y al final lo ayuda a uno con la nota si ve que la pulseó'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-04T00:00:00+00:00'::TIMESTAMPTZ, '5717762a63c58311aacb8af4411d522e597d8da0597e4d76884c1973d42e2b57'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'Deja bastante tarea al principio (dibujos a mano), pero esto ayuda para lograr el examen más fácilmente. Explica con presentaciones pero no aburre. Las clases se pasan súper rápido y hace receso en la mañana. Muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '4caf48e3a73ed39c067902c0b9bfd082d3b6b2dac44f0b3b476b2b5498e253f1'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El curso es bien pesado, con cualquier profesor lo es. Noel no tiene tanto tiempo dando el curso entonces se enreda un toque pero se ve que se esfuerza por darse a entender. Es paciente y comprensivo. Se nota que con el pasar del tiempo va a ser un gran profesor para este curso. Recomendado.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-12-02T00:00:00+00:00'::TIMESTAMPTZ, '872a3d34d5ca6b1e704b9cfa05f0dc90ee72f87321bf762b555ba834cccee701'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'Muy buen profe, aveces se enreda explicando, pero el lo vuelve a explicar las veces que sea necesario hasta que quede claro. Si uno no entiende a la hora practica, el va y le ayuda a uno hasta entenderlo. Recomendado 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '97f9b2d99ccc86e913df74b2db582642dbd77b77ae37b05cee7aaac532e51b82'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Es un curso muy pesado, sin embargo intenta hacerlo lo más llevadero posible. Una excelente persona y un buen profesor en crecimiento. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'f502ce710971331443d7ff2469df8ae3a03091a340037bf55c24b897dd3c7274'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ba031812730c859771b904baae48e9702e34a5cb6a18cd8b3bd8b3dc387f14d9'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El profe trata de hacer el curso llevadero (no lo es), aveces se enreda un poco dando la materia pero no es nada que se vuelva imposible de entender y si usted no entiende, entonces él explica cuántas veces sea necesario para que logre entender. No es tan rudo calificando.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '87f47384408cebb5d29dae114b489b076bb5faf0712090ad62c2343bd2fa068b'::TEXT, ARRAY[933]::BIGINT[]),
    (234::BIGINT, 'La materia con el suele ser interesante y aclara dudas si se le pregunta. Tiene un carácter complicado, a veces muy agradable y otras es gruñon'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c33680bb2f63d559dfc27f52159af0d917698e6dddba3c8e3975f5e31ebfcc25'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Buen profe!! Al principio deja como 5 tareas a mano que si requieren mucho tiempo pero siempre esta muy dispuesto a ayudar!! Después Autocad es muy fácil y el evalua super bien y no se hace tediosa. Muy bueno y recomendado:) ! Creo que el más fácil de los profes de dibujo !!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7429786e70c9a1932eb4dc62ef3366fe1839d31dcf2f234a9d784afcacbc89c7'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Muy buen profe, evacua todas las dudas que uno tenga. Súper recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '99127497986a96128322aea22515d7a8ce05cfba1463740b0549d2cef9d4a2fd'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Explica bien la materia y sube las presentaciones, además tiene paciencia y flexible, y le explica con calma cómo hacer las cosas bien. Se preocupa por el estudiante y hace prácticas en clase para prepararse para las evaluaciones. Espere tareas cada semana.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c0470ace7bc4e3fee9fda3362f79fba48df7aaf05ba58d00d3441e40386e5f14'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'El curso exige mucho tiempo y con él no es distinto. Pide bastantes tareas pero ayuda mucho si uno no entiende, siempre está dispuesto a volver a explicar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6d7ee032293c59c9ffe8dec272ab2f281a26dfd9d0ca72023339b26950fd61f7'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'Es bueno, sin embargo pide mucho más de lo que explica, a veces se enreda pero es muy paciente y amable para evacuar dudas. El curso es muy pasable'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-12-09T00:00:00+00:00'::TIMESTAMPTZ, '28837435b62f04c45ad8192570e11774d29be10914b3c169939e3c16f17aa008'::TEXT, ARRAY[610]::BIGINT[]),
    (234::BIGINT, 'el profesor es bueno, se preocupa bastante por ayudar a los estudiantes, evalúa suave y explica bien. Si le pone va a pasar muy bien'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '4ae35e8233c656064c7d96a8a83a22736da14c8ffb3f095d13f776fc2905301a'::TEXT, ARRAY[610]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
